 private static void route(DrawContext g,double cx,double cz,double scale,int sw,int sh,TownyMapConfig c,TeleportRoute r){double ax=sw/2d+(r.destination().x()-cx)*scale,ay=sh/2d+(r.destination().z()-cz)*scale,bx=sw/2d+(tx-cx)*scale,by=sh/2d+(tz-cz)*scale;var ice=IceRoadNetwork.tripFor(r);boolean drewIce=c.teleportRouteLineVisible&&IceRoadOverlay.renderSelectedRoute(g,cx,cz,scale,sw,sh,r.destination().x(),r.destination().z(),tx,tz,ice,c);if(c.teleportRouteLineVisible&&!drewIce){int n=TeleportRenderBudget.lineSteps(Math.hypot(bx-ax,by-ay));for(int i=0;i<=n;i+=2){double q=i/(double)n;g.fill((int)(ax+(bx-ax)*q)-1,(int)(ay+(by-ay)*q)-1,(int)(ax+(bx-ax)*q)+2,(int)(ay+(by-ay)*q)+2,0xFFFF58D0);}}if(c.teleportArrivalMarkerVisible&&ax>=-8&&ax<=sw+8&&ay>=-8&&ay<=sh+8){g.fill((int)ax-6,(int)ay-6,(int)ax+7,(int)ay+7,0xFFFFFFFF);g.fill((int)ax-4,(int)ay-4,(int)ax+5,(int)ay+5,0xFFFFB13B);}if(c.teleportDestinationMarkerVisible&&bx>=-8&&bx<=sw+8&&by>=-8&&by<=sh+8){g.fill((int)bx-6,(int)by-6,(int)bx+7,(int)by+7,0xFFFFFFFF);g.fill((int)bx-4,(int)by-4,(int)bx+5,(int)by+5,0xFF23C7E8);}int lx=(int)((ax+bx)/2),ly=(int)((ay+by)/2);String label=(int)Math.round(r.walkingDistance())+" "+Text.translatable("townymapaddon.teleport.blocks_short").getString();int lw=MinecraftClient.getInstance().textRenderer.getWidth(label);g.fill(lx-lw/2-4,ly-8,lx+lw/2+4,ly+7,0xCC171019);g.drawCenteredTextWithShadow(MinecraftClient.getInstance().textRenderer,label,lx,ly-4,0xFFFFFFFF);}
 public static boolean click(double mx,double my,int sw,int sh,TownyMapConfig c){if(!open)return false;if(IceRoadOverlay.clickSelectedRoute(mx,my,sw,sh,c)){plan=null;return true;}int x=c.teleportWindowX,y=c.teleportWindowY,h=Math.min(sh-y-6,136+VISIBLE*ROW+53);if(mx<x||mx>x+W||my<y||my>y+(minimized?HEAD:h))return false;if(my<y+HEAD){if(mx>x+W-25){open=false;}else if(mx>x+W-50)minimized=!minimized;else{dragging=true;dx=mx-x;dy=my-y;}return true;}if(minimized)return true;if(my>=y+29&&my<y+50&&mx>=x+W-82){TownyMapMod.forceRefreshTeleportData(tx,tz);plan=null;cleared=false;return true;}if(my>=y+65&&my<y+86){advanced=mx>=x+W/2;scroll=selected=0;plan=null;return true;}if(my>=y+90&&my<y+110){if(mx<x+122)view=1-view;else if(mx<x+238){c.teleportIncludeIceRoads=!c.teleportIncludeIceRoads;c.save();}else filter=(filter+1)%3;plan=null;scroll=selected=0;return true;}if(my>=y+h-48){if(my<y+h-26){if(mx<x+176){cleared=true;routes=List.of();}else XaeroWaypointBridge.removeTeleportWaypoints();}else setWaypoints();return true;}int index=scroll+(int)((my-(y+136))/ROW);if(index>=scroll&&index<routes.size()&&index<scroll+VISIBLE){selected=index;TeleportRoute r=routes.get(index);int ry=y+136+(index-scroll)*ROW;if(my>=ry+73&&my<ry+91){int n=(int)((mx-(x+14))/112);if(n>=0&&n<3){TownyMapMod.setTeleportSpawnReport(r.destination(),TeleportDestination.PhysicalAccess.values()[n]);plan=null;}}else if(my>=ry+20&&my<ry+38&&mx>=x+14&&mx<x+W-14){MinecraftClient.getInstance().keyboard.setClipboard(r.destination().command());}return true;}return true;}
 public static boolean release(TownyMapConfig c){if(!dragging)return false;dragging=false;c.save();return true;}public static boolean scroll(double x,double y,double amount,int sw,int sh,TownyMapConfig c){if(!open||x<c.teleportWindowX||x>c.teleportWindowX+W)return false;scroll=Math.clamp(scroll-(int)Math.signum(amount),0,Math.max(0,routes.size()-VISIBLE));return true;}
 private static void refresh(TownyMapConfig c){var next=TownyMapMod.teleportPlan(tx,tz);if(next==plan)return;plan=next;List<TeleportRoute> base=advanced?next.advanced():next.standard();routes=base.stream().filter(r->view==1||r.destination().eligibility()==TeleportDestination.Eligibility.ACCESSIBLE).filter(r->filter==0||filter==1&&r.destination().physicalAccess()==TeleportDestination.PhysicalAccess.ACCESSIBLE||filter==2&&r.destination().physicalAccess()==TeleportDestination.PhysicalAccess.OBSTRUCTED).toList();if(c.teleportIncludeIceRoads)routes=IceRoadNetwork.get().enrich(routes,tx,tz,c.iceRoadStationReports,filter==1);routes=routes.stream().sorted(Comparator.comparingDouble(TeleportRoute::walkingDistance)).toList();selected=Math.clamp(selected,0,Math.max(0,routes.size()-1));}
